def majority(arr):
    cand, cnt = None, 0
    for x in arr:
        if cnt == 0:
            cand = x
        cnt += 1 if x == cand else -1
    return cand if arr.count(cand) > len(arr) // 2 else -1

solution.java:
int majority(int[] a) {
    int cand = 0, cnt = 0;
    for (int x : a) { if (cnt == 0) cand = x; cnt += (x == cand) ? 1 : -1; }
    int c = 0; for (int x : a) if (x == cand) c++;
    return c > a.length / 2 ? cand : -1;
}

