from collections import deque

def num_islands(g):
    m, n, count = len(g), len(g[0]), 0
    for i in range(m):
        for j in range(n):
            if g[i][j] == '1':
                count += 1
                g[i][j] = '0'
                q = deque([(i, j)])
                while q:
                    r, c = q.popleft()
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x, y = r + dr, c + dc
                        if 0 <= x < m and 0 <= y < n and g[x][y] == '1':
                            g[x][y] = '0'
                            q.append((x, y))
    return count

def count_ways(n, mod=10**9 + 7):
    a, b = 1, 1  # ways(0), ways(1)
    for _ in range(n - 1):
        a, b = b, (a + b) % mod
    return b

